import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const isSameDay = (a: Date | null, b: Date) =>
  a != null && startOfDay(a).getTime() === b.getTime();

const quickOptions = [
  { label: 'Сегодня', getDate: () => shiftDays(0) },
  { label: 'Вчера', getDate: () => shiftDays(-1) },
  { label: 'Неделя назад', getDate: () => shiftDays(-7) },
];

export default function ReportDatePicker({
  defaultValue = null,
  onChange,
}: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(defaultValue);

  const selectDate = (next: Date | null) => {
    setDate(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {quickOptions.map((option) => {
          const optionDate = option.getDate();
          return (
            <JxChip
              key={option.label}
              active={isSameDay(date, optionDate)}
              onClick={() => selectDate(optionDate)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={selectDate} />
    </div>
  );
}

